-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.ete_llm_fresh_subgrade_patient_v1
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.ete_llm_fresh_subgrade_patient_v1 AS WITH graded AS (SELECT v.research_id, v.ete_grade AS ete_grade_llm, v.confidence, v.evidence_quote, v.ajcc8_implication FROM main.v_note_entities_llm_ete_subgrade_v1 AS v WHERE ((v."error" = 0) AND (v.ete_grade IN ('gross', 'microscopic', 'absent', 'unable_to_determine'))))SELECT research_id, CASE  WHEN ((max(CASE  WHEN ((ete_grade_llm = 'gross')) THEN (1) ELSE 0 END) = 1)) THEN ('gross') WHEN ((max(CASE  WHEN ((ete_grade_llm = 'microscopic')) THEN (1) ELSE 0 END) = 1)) THEN ('microscopic') WHEN ((max(CASE  WHEN ((ete_grade_llm = 'absent')) THEN (1) ELSE 0 END) = 1)) THEN ('absent') ELSE 'unable_to_determine' END AS ete_grade_fresh_llm, CAST(max(CASE  WHEN ((ete_grade_llm = 'gross')) THEN (1) ELSE 0 END) AS BOOLEAN) AS has_gross_fresh, CAST(max(CASE  WHEN ((ete_grade_llm = 'microscopic')) THEN (1) ELSE 0 END) AS BOOLEAN) AS has_micro_fresh, CAST(max(CASE  WHEN ((ete_grade_llm = 'absent')) THEN (1) ELSE 0 END) AS BOOLEAN) AS has_absent_fresh, string_agg(CASE  WHEN ((ete_grade_llm IN ('gross', 'microscopic', 'absent'))) THEN ("nullif"(evidence_quote, '')) ELSE NULL END, ' | ') AS fresh_evidence_quotes, max(confidence) AS fresh_best_confidence, string_agg(DISTINCT ajcc8_implication, ',') AS fresh_ajcc8_implications, count_star() AS n_fresh_mentions FROM graded GROUP BY research_id;
